{n:"A01 Broken Access Control",c:"OWASP Top 10:2025",w:"Users reaching data or actions they shouldn’t. The #1 web risk. Classic: change /invoice/123 to /124 and see someone else’s invoice.",p:"On every endpoint, check the logged-in user owns or may access the resource; deny by default.",r:"Authorisation checked only in the frontend; IDs trusted from the URL."},
{n:"A02 Security Misconfiguration",c:"OWASP Top 10:2025",w:"Default passwords, debug mode in production, open storage buckets, verbose error pages.",p:"Review config for production: debug off, secure headers, no default creds, private buckets.",r:"Stack traces shown to users; CORS set to *."},
{n:"A03 Software Supply Chain Failures",c:"OWASP Top 10:2025",w:"Risky or malicious dependencies, compromised build tools. Includes AI ‘hallucinated’ package names that attackers register.",p:"Before adding any package, confirm it exists, is maintained and widely used; pin versions; enable Dependabot.",r:"An install command for a package name you’ve never heard of."},
{n:"A04 Cryptographic Failures",c:"OWASP Top 10:2025",w:"Sensitive data unencrypted, weak hashing, home-made crypto.",p:"Hash passwords with Argon2id or bcrypt; HTTPS everywhere; encrypt sensitive fields at rest.",r:"MD5/SHA1 for passwords; custom ‘encryption’ functions."},
{n:"A05 Injection",c:"OWASP Top 10:2025",w:"Untrusted input executed as code: SQL injection, command injection, XSS.",p:"Use parameterised queries and the framework’s escaping; never build SQL or shell commands with string concatenation.",r:"`SELECT … WHERE id = ${id}`; innerHTML with user text."},
{n:"A06 Insecure Design",c:"OWASP Top 10:2025",w:"Flaws in the design itself, not the code: no rate limit on password reset, no limit on free trials.",p:"Threat-model this feature with STRIDE before coding; list abuse cases and mitigations.",r:"Features designed only for the happy path."},
{n:"A07 Authentication Failures",c:"OWASP Top 10:2025",w:"Weak login, sessions that never expire, no MFA, credential stuffing.",p:"Use a proven auth provider/library; add MFA, rate limiting and secure session cookies.",r:"Hand-rolled login with JWTs stored in localStorage."},
{n:"A08 Software & Data Integrity Failures",c:"OWASP Top 10:2025",w:"Trusting updates, plugins or serialized data without verification.",p:"Verify signatures on updates; never deserialize untrusted data into objects.",r:"Auto-update over HTTP; pickle/BinaryFormatter on user files."},
{n:"A09 Logging & Alerting Failures",c:"OWASP Top 10:2025",w:"Attacks go unnoticed because nothing is logged or nobody is alerted.",p:"Log logins, permission failures and admin actions with user and time; alert on spikes; never log passwords or tokens.",r:"No logs at all, or logs full of personal data."},
{n:"A10 Mishandling Exceptional Conditions",c:"OWASP Top 10:2025",w:"Errors that leave the system in an unsafe state: failing open, half-finished transactions.",p:"On error, fail closed: deny access, roll back the transaction, show a generic message.",r:"catch { } that lets the request continue as if authorised."},
{n:"Secrets Management",c:"Practices",w:"API keys and passwords never go in code or Git. Use environment variables or a secrets vault.",p:"Move all secrets to environment variables; add a .env.example; add secret scanning to CI.",r:"Keys in frontend code or committed .env files."},
{n:"Input Validation",c:"Practices",w:"Define what valid input looks like (type, length, range, format) and reject everything else.",p:"Validate all inputs with a schema (Zod, Pydantic, FluentValidation) at the API boundary.",r:""},
{n:"Rate Limiting",c:"Practices",w:"Limit requests per user/IP to stop brute force, scraping and runaway AI bills.",p:"Add rate limits to login, signup, password reset and any endpoint that calls a paid AI API.",r:"An open endpoint that calls an LLM with no limit."},
{n:"Dependency Scanning & SBOM",c:"Practices",w:"Automatically check libraries for known vulnerabilities; keep a Software Bill of Materials (list of components). Now required by the EU Cyber Resilience Act for many products.",p:"Add Dependabot/Renovate and generate an SBOM (CycloneDX) in CI.",r:""},
{n:"Threat Modelling (STRIDE)",c:"Practices",w:"Before building, ask what could go wrong: Spoofing, Tampering, Repudiation, Information disclosure, Denial of service, Elevation of privilege.",p:"Do a STRIDE threat model of this architecture and list the top 5 risks with mitigations.",r:""},
{n:"Prompt Injection",c:"AI-specific (OWASP LLM)",w:"Text in a document, web page or email that tricks your AI feature into ignoring its instructions.",p:"Treat all retrieved or user-supplied text as data; never let it trigger tools or reveal the system prompt.",r:"An AI agent that reads emails and can also send them, with no approval step."},
{n:"Excessive Agency",c:"AI-specific (OWASP LLM)",w:"Giving an AI tools or permissions beyond what the task needs.",p:"Give the agent read-only tools by default; require human approval for writes, payments and deletes.",r:""},
{n:"Sensitive Data in Prompts",c:"AI-specific (OWASP LLM)",w:"Personal or confidential data sent to an AI provider, or leaked back in answers.",p:"Strip personal data before sending to the model; check the provider’s data-retention terms.",r:"Customer records pasted into prompts for ‘context’."}
