/* ---------- SDLC ---------- */
const SDLC=[
{n:"Waterfall",c:"Plan-driven",w:"Phases in strict order: requirements → design → build → test → deploy. Change is expensive.",ok:"Fixed scope, contracts, hardware-bound projects.",bad:"Unclear requirements; most software products.",vc:"Feels natural (‘tell AI everything, then build’) but hides problems until the end."},
{n:"V-Model",c:"Plan-driven",w:"Waterfall where every design level has a matching test level: requirements ↔ acceptance tests, architecture ↔ integration tests, design ↔ unit tests.",ok:"Safety and regulated systems (IEC 62304, ISO 26262, DO-178C, rail). The ATM tier.",bad:"Fast-moving products.",vc:"Borrow the idea: write each test level against its matching spec."},
{n:"Iterative & Incremental",c:"Adaptive",w:"Build in slices; each slice is a working part of the whole.",ok:"Almost everything.",bad:"",vc:"Natural fit: one feature per AI session."},
{n:"Spiral",c:"Risk-driven",w:"Loops of plan → risk analysis → build → evaluate; tackles the biggest risk first.",ok:"Large, high-risk projects.",bad:"Small projects (heavy).",vc:"Steal ‘riskiest thing first’: prototype the hardest part before the easy UI."},
{n:"Agile (Scrum)",c:"Adaptive",w:"Fixed 1–2 week sprints, a prioritised backlog, daily stand-up, review and retrospective.",ok:"Product teams of 3–9 people.",bad:"Solo work (ceremonies feel heavy).",vc:"Use the backlog and the sprint goal; skip the meetings."},
{n:"Kanban",c:"Adaptive",w:"A board (To do → Doing → Review → Done) with limits on work in progress. Continuous flow, no sprints.",ok:"Solo builders, support work, maintenance.",bad:"",vc:"The best fit for most vibe coders: limit yourself to 1–2 items in progress."},
{n:"Extreme Programming (XP)",c:"Adaptive",w:"Engineering practices: TDD, pair programming, continuous integration, small releases, refactoring.",ok:"Code quality focus.",bad:"",vc:"AI is your pair: you drive intent, it types; you review every change."},
{n:"Lean / Lean Startup",c:"Adaptive",w:"Cut waste; build–measure–learn with a minimum viable product.",ok:"New products with unknown demand.",bad:"",vc:"Ship the smallest thing that tests your idea with real users."},
{n:"DevOps",c:"Culture + automation",w:"Development and operations as one loop: CI/CD, infrastructure as code, monitoring, fast feedback.",ok:"Any software that runs as a service.",bad:"",vc:"Set up CI and auto-deploy to staging in week one."},
{n:"DevSecOps",c:"Culture + automation",w:"DevOps with security built into every stage: scanning, threat models, secrets checks in the pipeline.",ok:"Anything public or with personal data.",bad:"",vc:"Add security scans to CI from the start: it costs minutes."},
{n:"SAFe / LeSS",c:"Scaled agile",w:"Frameworks for coordinating agile across many teams.",ok:"Large enterprises.",bad:"Small teams.",vc:"Not relevant until you have several teams."},
{n:"Shape Up",c:"Adaptive",w:"Basecamp’s method: shape a problem, bet on it for a 6-week cycle, then a cool-down.",ok:"Small product teams.",bad:"",vc:"Give each feature a fixed time budget; cut scope, not quality."}
];
